using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.Text.Json;

string output = args[2]; Directory.CreateDirectory(output);
using var propsSource = new Bitmap(args[0]); using var characterSource = new Bitmap(args[1]);
using var atlas = new Bitmap(1024,1024); using var g = Graphics.FromImage(atlas);
g.InterpolationMode=InterpolationMode.NearestNeighbor;g.PixelOffsetMode=PixelOffsetMode.Half;g.Clear(Color.Transparent);
string[] names={"house","shop","spring","summer","autumn","winter","crate","well","barrel","sign","flowers","rocks","carrot","turnip","potato","tomato","corn","berry","pumpkin","cabbage","water","hoe","seeds","portrait"};
var regions=new Dictionary<string,int[]>();int cursorX=2,cursorY=2,rowHeight=0;
Rectangle Bounds(Bitmap source,Rectangle cell){int x0=cell.Right,y0=cell.Bottom,x1=cell.X,y1=cell.Y;for(int y=cell.Y;y<cell.Bottom;y++)for(int x=cell.X;x<cell.Right;x++)if(source.GetPixel(x,y).A>100){x0=Math.Min(x0,x);x1=Math.Max(x1,x);y0=Math.Min(y0,y);y1=Math.Max(y1,y);}return Rectangle.FromLTRB(x0,y0,x1+1,y1+1);}
void Put(string name,Rectangle source,int width){int h=Math.Max(1,(int)Math.Round((double)source.Height/source.Width*width));if(cursorX+width+2>1024){cursorX=2;cursorY+=rowHeight+4;rowHeight=0;}g.DrawImage(propsSource,new Rectangle(cursorX,cursorY,width,h),source,GraphicsUnit.Pixel);regions[name]=new[]{cursorX,cursorY,width,h};cursorX+=width+4;rowHeight=Math.Max(rowHeight,h);}
int[] columns={0,278,545,788,1040,1290,1536},rows={0,281,515,739,1024};
for(int i=0;i<24;i++){int col=i%6,row=i/6;var cell=Rectangle.FromLTRB(columns[col],rows[row],columns[col+1],rows[row+1]);var b=Bounds(propsSource,cell);Put(names[i],b,i<2?160:i<6?112:i<12?48:i<20?40:32);if(i>=12&&i<20){var young=new Rectangle(b.X,b.Y,b.Width,Math.Max(1,(int)(b.Height*.68)));Put("young-"+names[i],young,30);}}
// Two tiny planted-leaf clusters, authored pixels; dedicated per-crop early stages remain artist review work.
int sx=cursorX,sy=cursorY;using(var b=new SolidBrush(Color.FromArgb(84,119,61)))g.FillRectangle(b,sx+5,sy+3,4,10);using(var b=new SolidBrush(Color.FromArgb(152,182,92))){g.FillRectangle(b,sx,sy,6,4);g.FillRectangle(b,sx+8,sy+2,6,4);}regions["sprout"]=new[]{sx,sy,14,14};
atlas.Save(Path.Combine(output,"props.png"));File.WriteAllText(Path.Combine(output,"regions.json"),JsonSerializer.Serialize(regions,new JsonSerializerOptions{WriteIndented=true}));
using var chars=new Bitmap(160,224);using(var cg=Graphics.FromImage(chars)){cg.InterpolationMode=InterpolationMode.NearestNeighbor;cg.PixelOffsetMode=PixelOffsetMode.Half;for(int row=0;row<4;row++)for(int col=0;col<4;col++){var b=Bounds(characterSource,new Rectangle(col*characterSource.Width/4,row*characterSource.Height/4,characterSource.Width/4,characterSource.Height/4));int h=52,w=Math.Min(38,(int)Math.Round((double)b.Width/b.Height*h));cg.DrawImage(characterSource,new Rectangle(col*40+(40-w)/2,row*56+54-h,w,h),b,GraphicsUnit.Pixel);}}chars.Save(Path.Combine(output,"characters.png"));
Color C(string h)=>ColorTranslator.FromHtml("#"+h);
using var terrain=new Bitmap(512,128);var rng=new Random(617);
string[] grass={"7e9959","6f9552","be9361","c0d2c4"};
using(var tg=Graphics.FromImage(terrain)){void R(Color c,int x,int y,int w,int h){using var b=new SolidBrush(c);tg.FillRectangle(b,x,y,w,h);}for(int season=0;season<4;season++)for(int tile=0;tile<16;tile++){int ox=tile*32,oy=season*32;var baseColor=tile<4?C(grass[season]):tile<8?C("c5ad7c"):tile<11?C(tile==8?"997050":tile==9?"805d42":"664c3c"):C(grass[season]);R(baseColor,ox,oy,32,32);for(int i=0;i<68;i++){int x=ox+rng.Next(32),y=oy+rng.Next(32),d=rng.Next(-14,15);R(Color.FromArgb(Math.Clamp(baseColor.R+d,0,255),Math.Clamp(baseColor.G+d,0,255),Math.Clamp(baseColor.B+d,0,255)),x,y,rng.Next(1,4),1);}if(tile<4){for(int n=0;n<9;n++){int x=ox+rng.Next(2,29),y=oy+rng.Next(5,28);R(C(season==3?"e4e9df":"a5b67a"),x,y,1,3);R(C(season==3?"a3b4b1":"557341"),x-2,y+2,1,2);R(C(season==3?"e4e9df":"a5b67a"),x+2,y+1,1,2);}}else if(tile<8){for(int y=4;y<32;y+=8){R(C("ad9267"),ox,oy+y,32,1);for(int x=tile%2*6;x<32;x+=13)R(C("d5c191"),ox+x,oy+y+1,1,7);}}else if(tile<11){for(int y=5;y<31;y+=7){R(C(tile==10?"493a30":"65462f"),ox+2,oy+y,28,2);R(C(tile==10?"876544":"b08858"),ox+3,oy+y-1,26,1);}R(C("614b35"),ox,oy,32,1);R(C("614b35"),ox,oy,1,32);}else if(tile==12){R(C("5e4634"),ox,oy+15,32,4);R(C("a57b4f"),ox,oy+15,32,1);R(C("574333"),ox+3,oy+8,5,20);R(C("c49b66"),ox+4,oy+8,2,18);R(C("a17951"),ox+2,oy+7,7,2);}}}terrain.Save(Path.Combine(output,"terrain.png"));
using var pond=new Bitmap(192,128);using(var pg=Graphics.FromImage(pond)){pg.SmoothingMode=SmoothingMode.None;var shore=new[]{new Point(8,39),new Point(35,11),new Point(77,7),new Point(99,20),new Point(150,10),new Point(180,35),new Point(187,83),new Point(158,111),new Point(121,121),new Point(76,114),new Point(46,121),new Point(12,89)};using(var b=new SolidBrush(C("6b7051")))pg.FillPolygon(b,shore);pg.TranslateTransform(96,64);pg.ScaleTransform(.93f,.89f);pg.TranslateTransform(-96,-64);using(var b=new SolidBrush(C("94b399")))pg.FillPolygon(b,shore);pg.TranslateTransform(96,64);pg.ScaleTransform(.91f,.87f);pg.TranslateTransform(-96,-64);using(var b=new SolidBrush(C("568e91")))pg.FillPolygon(b,shore);for(int i=0;i<90;i++){using var b=new SolidBrush(i%3==0?C("83b4ad"):C("659b9c"));pg.FillRectangle(b,rng.Next(30,163),rng.Next(30,92),rng.Next(4,14),1);}}pond.Save(Path.Combine(output,"pond.png"));
using var shadow=new Bitmap(64,24);using(var sg=Graphics.FromImage(shadow)){for(int i=0;i<4;i++){using var b=new SolidBrush(Color.FromArgb(15,33,44,33));sg.FillEllipse(b,i*4,i*2,64-i*8,24-i*4);}}shadow.Save(Path.Combine(output,"shadow.png"));
using var glow=new Bitmap(128,128);for(int y=0;y<128;y++)for(int x=0;x<128;x++){double d=Math.Sqrt((x-64)*(x-64)+(y-64)*(y-64))/64;glow.SetPixel(x,y,Color.FromArgb((int)(Math.Pow(Math.Max(0,1-d),2)*255),255,255,255));}glow.Save(Path.Combine(output,"glow.png"));
using var stake=new Bitmap(4,28);using(var sg=Graphics.FromImage(stake)){sg.Clear(C("76563b"));using var b=new SolidBrush(C("bb945e"));sg.FillRectangle(b,0,0,1,28);}stake.Save(Path.Combine(output,"stake.png"));
string sourceText="[gd_resource type=\"TileSet\" load_steps=3 format=3]\n[ext_resource type=\"Texture2D\" path=\"res://Assets/terrain.png\" id=\"1\"]\n[sub_resource type=\"TileSetAtlasSource\" id=\"Atlas\"]\ntexture = ExtResource(\"1\")\ntexture_region_size = Vector2i(32, 32)\n";for(int y=0;y<4;y++)for(int x=0;x<16;x++)sourceText+=$"{x}:{y}/0 = 0\n";sourceText+="[resource]\ntile_size = Vector2i(32, 32)\nsources/0 = SubResource(\"Atlas\")\n";File.WriteAllText(Path.Combine(output,"FarmTiles.tres"),sourceText);
